import Foundation

/// 捕获时的规则入口: 先过固定的剪贴板标记 (不受用户规则影响), 再交给用户规则
/// (`CaptureEvaluator`, 白名单优先, 再黑名单)。
public struct RulesEngine: Sendable {
    /// 剪贴板里带这些标记的内容一律不收, 用户规则管不到。nspasteboard.org 约定的三种
    /// 通用标记、几个 app 自有的同类标记 (同一页面与 Maccy 默认忽略列表), 加上 Copy
    /// 自己粘贴时的标记。
    public static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",           // 1Password 旧版的隐藏内容标记
        "net.antelle.keeweb",                  // KeeWeb
        "de.petermaurer.TransientPasteboardType", // TextExpander、Butler 等
        "com.typeit4me.clipping",              // TypeIt4Me
        "Pasteboard generator type",           // Typinator
        CopyPasteboard.selfMarkerType,
    ]
    /// 通用剪贴板 (Handoff) 接力过来的内容带这个标记 (nspasteboard.org 收录)。
    public static let remoteClipboardType = "com.apple.is-remote-clipboard"

    public let evaluator: CaptureEvaluator

    public init(rules: CaptureRules = CaptureRules()) {
        evaluator = CaptureEvaluator(rules: rules)
    }

    /// 只排除这些 app 的规则 (旧接口, 测试用)。
    public init(excludedBundleIDs: Set<String>) {
        var rules = CaptureRules()
        rules.blacklist.apps = excludedBundleIDs.sorted()
        self.init(rules: rules)
    }

    public var rules: CaptureRules { evaluator.rules }

    public static func hasSkipMarker(_ types: [String]) -> Bool {
        types.contains(where: skipTypes.contains)
    }

    /// 读内容之前能否继续: 没有固定标记, 来源 app 和通用剪贴板也没被规则挡下。
    public func shouldCapture(types: [String], sourceBundleID: String?) -> Bool {
        guard !Self.hasSkipMarker(types) else { return false }
        return evaluator.preflight(sourceBundleID: sourceBundleID,
                                   isRemote: types.contains(Self.remoteClipboardType)) == .proceed
    }
}
